-- 0005_sponsorship_proposal.sql
create table if not exists {{schema}}."sponsorship_proposal" (
    "id" bigint generated by default as identity primary key,
    "company_id" bigint not null default 1,
    "nomor_proposal" text collate "C" not null,
    "tanggal" text collate "C" not null,
    "referensi" text collate "C",
    "kegiatan" text collate "C",
    "app_amount" double precision default 0,
    "agri_amount" double precision default 0,
    "energy_amount" double precision default 0,
    "land_amount" double precision default 0,
    "finance_amount" double precision default 0,
    "total_amount" double precision default 0,
    "diajukan_oleh" text collate "C" default 'AR/JT',
    "versi" text collate "C" default '',
    "status" text collate "C" default 'Open',
    "approval_date" text collate "C" default '',
    "catatan" text collate "C" default 'Nilai Sumbangan diatas netto excluded/ diluar pajak PPN/PPh',
    "created_at" text collate "C" default to_char(now() at time zone 'utc', 'YYYY-MM-DD HH24:MI:SS'),
    "updated_at" text collate "C" default to_char(now() at time zone 'utc', 'YYYY-MM-DD HH24:MI:SS'),
    unique ("nomor_proposal")
);

create index if not exists idx_sponsorship_proposal_company on {{schema}}."sponsorship_proposal" ("company_id", "tanggal");
